using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEngine.UIElements;
public static class PanelContinuityCheck {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static Type type;static object lease;static GameObject owner;static PanelSettings first;static int count,frame;static float scale;
 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");type=typeof(EchoSphere.Runtime.EchoSphereRuntime).Assembly.GetType("EchoSphere.Presentation.NativePanelLease");count=frame=0;Create();UnityEditor.EditorApplication.update+=Tick;return "RUNNING";}
 static void Create(){owner=new GameObject("Panel continuity acceptance");scale=count%2==0?1:2;lease=Activator.CreateInstance(type,F,null,new object[]{owner,"Continuity acceptance",1700,null,(float?)scale},null);var panel=(PanelSettings)type.GetProperty("Panel",F).GetValue(lease);if(count==0)first=panel;if(panel!=first||panel.scale!=scale)throw new Exception("Panel continuity/density lost");var doc=(UIDocument)type.GetProperty("Document",F).GetValue(lease);var box=new VisualElement();box.style.width=100;box.style.height=100;box.style.overflow=Overflow.Hidden;box.style.borderTopLeftRadius=12;var blur=new FilterFunction(FilterFunctionType.Blur);blur.AddParameter(new FilterParameter(4));box.style.backdropFilter=new System.Collections.Generic.List<FilterFunction>{blur};doc.rootVisualElement.Add(box);}
 static void Tick(){if(++frame<5)return;frame=0;try{((IDisposable)lease).Dispose();UnityEngine.Object.Destroy(owner);lease=null;if(++count==20){UnityEditor.EditorApplication.update-=Tick;File.WriteAllText("Library/panel-continuity.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{result="PASS",cycles=count,panelAlive=first!=null,scope="20 retained native panel/filter/rounded clip document retirement cycles, alternating density; no gameplay state writes"}));return;}Create();}catch(Exception e){UnityEditor.EditorApplication.update-=Tick;File.WriteAllText("Library/panel-continuity.json",e.ToString());}}
}
